import{_ as t,H as i,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"57 | 套路篇：Linux 性能工具速查","description":"","frontmatter":{},"headers":[{"level":2,"title":"性能工具速查","slug":"性能工具速查","link":"#性能工具速查","children":[]},{"level":2,"title":"CPU性能工具","slug":"cpu性能工具","link":"#cpu性能工具","children":[]},{"level":2,"title":"内存性能工具","slug":"内存性能工具","link":"#内存性能工具","children":[]},{"level":2,"title":"磁盘I/O性能工具","slug":"磁盘i-o性能工具","link":"#磁盘i-o性能工具","children":[]},{"level":2,"title":"网络性能工具","slug":"网络性能工具","link":"#网络性能工具","children":[]},{"level":2,"title":"基准测试工具","slug":"基准测试工具","link":"#基准测试工具","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考","slug":"思考","link":"#思考","children":[]}],"relativePath":"Linux性能优化实战/57-套路篇：Linux性能工具速查.md","filePath":"Linux性能优化实战/57-套路篇：Linux性能工具速查.md","lastUpdated":1779815995000}'),s={name:"Linux性能优化实战/57-套路篇：Linux性能工具速查.md"};function r(l,e,p,o,E,h){return i(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_57-套路篇-linux-性能工具速查" tabindex="-1">57 | 套路篇：Linux 性能工具速查 <a class="header-anchor" href="#_57-套路篇-linux-性能工具速查" aria-label="Permalink to &quot;57 | 套路篇：Linux 性能工具速查&quot;">​</a></h1><p>你好，我是倪朋飞。</p><p>上一节，我带你一起梳理了常见的性能优化思路，先简单回顾一下。</p><p>我们可以从系统和应用程序两个角度，来进行性能优化。</p><ul><li><p>从系统的角度来说，主要是对 CPU、内存、网络、磁盘 I/O 以及内核软件资源等进行优化。</p></li><li><p>而从应用程序的角度来说，主要是简化代码、降低 CPU 使用、减少网络请求和磁盘 I/O，并借助缓存、异步处理、多进程和多线程等，提高应用程序的吞吐能力。</p></li></ul><p>性能优化最好逐步完善，动态进行。不要追求一步到位，而要首先保证能满足当前的性能要求。性能优化通常意味着复杂度的提升，也意味着可维护性的降低。</p><p>如果你发现单机的性能调优带来过高复杂度，一定不要沉迷于单机的极限性能，而要从软件架构的角度，以水平扩展的方法来提升性能。</p><p>工欲善其事，必先利其器。我们知道，在性能分析和优化时，借助合适的性能工具，可以让整个过程事半功倍。你还记得有哪些常用的性能工具吗？今天，我就带你一起梳理一下常用的性能工具，以便你在需要时，可以迅速找到自己想要的。</p><h2 id="性能工具速查" tabindex="-1">性能工具速查 <a class="header-anchor" href="#性能工具速查" aria-label="Permalink to &quot;性能工具速查&quot;">​</a></h2><p>在梳理性能工具之前，首先给你提一个问题，那就是，在什么情况下，我们才需要去查找、挑选性能工具呢？你可以先自己想一下，再继续下面的内容。</p><p>其实在我看来，只有当你想了解某个性能指标，却不知道该怎么办的时候，才会想到，“要是有一个性能工具速查表就好了”这个问题。如果已知一个性能工具可用，我们更多会去查看这个工具的手册，找出它的功能、用法以及注意事项。</p><p>关于工具手册的查看，man 应该是我们最熟悉的方法，我在专栏中多次介绍过。实际上，除了 man 之外，还有另外一个查询命令手册的方法，也就是 info。</p><p>info 可以理解为 man 的详细版本，提供了诸如节点跳转等更强大的功能。相对来说，man 的输出比较简洁，而 info 的输出更详细。所以，我们通常使用 man 来查询工具的使用方法，只有在man 的输出不太好理解时，才会再去参考 info 文档。</p><p>当然，我说过了，要查询手册，前提一定是已知哪个工具可用。如果你还不知道要用哪个工具，就要根据想了解的指标，去查找有哪些工具可用。这其中：</p><ul><li><p>有些工具不需要额外安装，就可以直接使用，比如内核的 /proc 文件系统；</p></li><li><p>而有些工具，则需要安装额外的软件包，比如 sar、pidstat、iostat 等。</p></li></ul><p><strong>所以，在选择性能工具时，除了要考虑性能指标这个目的外，还要结合待分析的环境来综合考虑</strong>。比如，实际环境是否允许安装软件包，是否需要新的内核版本等。</p><p>明白了工具选择的基本原则后，我们来看 Linux 的性能工具。首先还是要推荐下面这张图，也就是Brendan Gregg 整理的性能工具谱图。我在专栏中多次提到过，你肯定也已经参考过。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/b07ca95ef8a3d2c89b0996a042d33901.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/b07ca95ef8a3d2c89b0996a042d33901.png" alt=""></a></p><p>（图片来自 <a href="http://www.brendangregg.com/linuxperf.html" target="_blank" rel="noreferrer">brendangregg.com</a>）</p><p>这张图从 Linux 内核的各个子系统出发，汇总了对各个子系统进行性能分析时，你可以选择的工具。不过，虽然这个图是性能分析最好的参考资料之一，它其实还不够具体。</p><p>比如，当你需要查看某个性能指标时，这张图里对应的子系统部分，可能有多个性能工具可供选择。但实际上，并非所有这些工具都适用，具体要用哪个，还需要你去查找每个工具的手册，对比分析做出选择。</p><p>那么，有没有更好的方法来理解这些工具呢？ <strong>我的建议，还是从性能指标出发，根据性能指标的不同，将性能工具划分为不同类型</strong>。比如，最常见的就是可以根据 CPU、内存、磁盘 I/O 以及网络的各类性能指标，将这些工具进行分类。</p><p>接下来，我就从 CPU、内存、磁盘 I/O 以及网络等几个角度，梳理这些常见的 Linux 性能工具，特别是从性能指标的角度出发，理清楚到底有哪些工具，可以用来监测特定的性能指标。这些工具，实际上贯穿在我们专栏各模块的各个案例中。为了方便你查看，我将它们都整理成了表格，并增加了每个工具的使用场景。</p><h2 id="cpu性能工具" tabindex="-1">CPU性能工具 <a class="header-anchor" href="#cpu性能工具" aria-label="Permalink to &quot;CPU性能工具&quot;">​</a></h2><p>首先，从 CPU 的角度来说，主要的性能指标就是 CPU 的使用率、上下文切换以及 CPU Cache 的命中率等。下面这张图就列出了常见的 CPU 性能指标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/9a211905538faffb5b3221ee01776a69.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/9a211905538faffb5b3221ee01776a69.png" alt=""></a></p><p>从这些指标出发，再把 CPU 使用率，划分为系统和进程两个维度，我们就可以得到，下面这个 CPU 性能工具速查表。注意，因为每种性能指标都可能对应多种工具，我在每个指标的说明中，都帮你总结了这些工具的特点和注意事项。这些也是你需要特别关注的地方。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/28cb85011289f83804c51c1fb275dab0.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/28cb85011289f83804c51c1fb275dab0.png" alt=""></a></p><h2 id="内存性能工具" tabindex="-1">内存性能工具 <a class="header-anchor" href="#内存性能工具" aria-label="Permalink to &quot;内存性能工具&quot;">​</a></h2><p>接着我们来看内存方面。从内存的角度来说，主要的性能指标，就是系统内存的分配和使用、进程内存的分配和使用以及 SWAP 的用量。下面这张图列出了常见的内存性能指标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/ee36f73b9213063b3bcdaed2245944c0.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/ee36f73b9213063b3bcdaed2245944c0.png" alt=""></a></p><p>从这些指标出发，我们就可以得到如下表所示的内存性能工具速查表。同 CPU 性能工具一样，这儿我也帮你梳理了，常见工具的特点和注意事项。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/79ad5caf0a2c105b7e9ce77877d493f8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/79ad5caf0a2c105b7e9ce77877d493f8.png" alt=""></a></p><p>注：最后一行pcstat的源码链接为 <a href="https://github.com/tobert/pcstat" target="_blank" rel="noreferrer">https://github.com/tobert/pcstat</a></p><h2 id="磁盘i-o性能工具" tabindex="-1">磁盘I/O性能工具 <a class="header-anchor" href="#磁盘i-o性能工具" aria-label="Permalink to &quot;磁盘I/O性能工具&quot;">​</a></h2><p>接下来，从文件系统和磁盘 I/O 的角度来说，主要性能指标，就是文件系统的使用、缓存和缓冲区的使用，以及磁盘 I/O 的使用率、吞吐量和延迟等。下面这张图列出了常见的 I/O 性能指标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/723431a944034b51a9ef13a8a1d4d03b.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/723431a944034b51a9ef13a8a1d4d03b.png" alt=""></a></p><p>从这些指标出发，我们就可以得到，下面这个文件系统和磁盘 I/O 性能工具速查表。同 CPU和内存性能工具一样，我也梳理出了这些工具的特点和注意事项。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/c232dcb4185f7b7ba95c126889cf6fa3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/c232dcb4185f7b7ba95c126889cf6fa3.png" alt=""></a></p><h2 id="网络性能工具" tabindex="-1">网络性能工具 <a class="header-anchor" href="#网络性能工具" aria-label="Permalink to &quot;网络性能工具&quot;">​</a></h2><p>最后，从网络的角度来说，主要性能指标就是吞吐量、响应时间、连接数、丢包数等。根据 TCP/IP 网络协议栈的原理，我们可以把这些性能指标，进一步细化为每层协议的具体指标。这里我同样用一张图，分别从链路层、网络层、传输层和应用层，列出了各层的主要指标。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/37d04c213acfa650bd7467e3000356a4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/37d04c213acfa650bd7467e3000356a4.png" alt=""></a></p><p>从这些指标出发，我们就可以得到下面的网络性能工具速查表。同样的，我也帮你梳理了各种工具的特点和注意事项。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/5dde213baffd7811ab73c82883b2a75d.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/5dde213baffd7811ab73c82883b2a75d.png" alt=""></a></p><h2 id="基准测试工具" tabindex="-1">基准测试工具 <a class="header-anchor" href="#基准测试工具" aria-label="Permalink to &quot;基准测试工具&quot;">​</a></h2><p>除了性能分析外，很多时候，我们还需要对系统性能进行基准测试。比如，</p><ul><li><p>在文件系统和磁盘 I/O 模块中，我们使用 fio 工具，测试了磁盘 I/O 的性能。</p></li><li><p>在网络模块中，我们使用 iperf、pktgen 等，测试了网络的性能。</p></li><li><p>而在很多基于 Nginx 的案例中，我们则使用 ab、wrk 等，测试 Nginx 应用的性能。</p></li></ul><p>除了专栏里介绍过的这些工具外，对于 Linux 的各个子系统来说，还有很多其他的基准测试工具可能会用到。下面这张图，是 Brendan Gregg 整理的 Linux 基准测试工具图谱，你可以保存下来，在需要时参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/f094f489049602e1058e02edc708e6e9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Linux%E6%80%A7%E8%83%BD%E4%BC%98%E5%8C%96%E5%AE%9E%E6%88%98/images/89306/f094f489049602e1058e02edc708e6e9.png" alt=""></a></p><p>（图片来自 <a href="http://www.brendangregg.com/linuxperf.html" target="_blank" rel="noreferrer">brendangregg.com</a>）</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>今天，我们一起梳理了常见的性能工具，并从 CPU、内存、文件系统和磁盘 I/O、网络以及基准测试等不同的角度，汇总了各类性能指标所对应的性能工具速查表。</p><p>当分析性能问题时，大的来说，主要有这么两个步骤：</p><ul><li><p>第一步，从性能瓶颈出发，根据系统和应用程序的运行原理，确认待分析的性能指标。</p></li><li><p>第二步，根据这些图表，选出最合适的性能工具，然后了解并使用工具，从而更快观测到需要的性能数据。</p></li></ul><p>虽然 Linux 的性能指标和性能工具都比较多，但熟悉了各指标含义后，你自然就会发现这些工具同性能指标间的关联。顺着这个思路往下走，掌握这些工具的选用其实并不难。</p><p>当然，正如咱们专栏一直强调的，不要把性能工具当成性能分析和优化的全部。</p><ul><li><p>一方面，性能分析和优化的核心，是对系统和应用程序运行原理的掌握，而性能工具只是辅助你更快完成这个过程的帮手。</p></li><li><p>另一方面，完善的监控系统，可以提供绝大部分性能分析所需的基准数据。从这些数据中，你很可能就能大致定位出性能瓶颈，也就不用再去手动执行各类工具了。</p></li></ul><h2 id="思考" tabindex="-1">思考 <a class="header-anchor" href="#思考" aria-label="Permalink to &quot;思考&quot;">​</a></h2><p>最后，我想邀请你一起来聊聊，你都使用过哪些性能工具。你通常是怎么选择性能工具的？又是如何想到要用这些性能工具，来排查和分析性能问题的？你可以结合我的讲述，总结自己的思路。</p><p>欢迎在留言区和我讨论，也欢迎你把这篇文章分享给你的同事、朋友。我们一起在实战中演练，在交流中进步。</p>',60)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
